insert into public.padroes (id,nome,reel_origem,perfil,razao_vs_mediana,razao_comentarios,categoria_produto,tipo_gancho,estrutura,texto_fixo_resumo,tem_fala,n_cortes,duracao_s,evidencia,formato_rafa,mecanismo,nao_copiar,coletado_em) values
('investigacao-polemica','Investigação de uma dúvida que todo mundo tem','https://www.instagram.com/reel/Dfk0m0xh3t8/','adammitch',16.98,11.74,'base, pó e blush (lançamento Fran by FR)','react de polêmica + promessa de investigação','montagem de clipes da polêmica (0-11s) > compra > teste meio a meio > swatches > veredito','textos dos clipes de terceiros (lançamento, ''POV primeiro uso'', ''a base oxida?'')',true,120,569.3,'observado (estrutura); hipotese (causa do desempenho)',5,'Abrir com o que as pessoas estão dizendo sobre o produto (a dúvida ou reclamação que circula), prometer investigar, mostrar que comprou, fazer um teste dividido (metade/metade ou antes/depois) e fechar com veredito claro. Ritmo rápido, muitos cortes curtos.','Não usar clipes, prints ou vídeos de outras criadoras; trazer a dúvida em texto na tela ou na fala dela. Não criar nem alimentar polêmica contra marca: a dúvida é sobre o produto, testada com honestidade. Nada da persona ''jornalista investigativa'' do original.','2026-11-23'),
('lista-com-regra','Lista com uma regra única','https://www.instagram.com/reel/De0I4M4OsYv/','natgagliotti',2.1,25.69,'necessaire completa de nacionais e baratos','desafio com regra única (''acabamento de luxo'')','necessaire na mão > 13 produtos em sequência, ~10s cada, com uma frase de benefício > lip combo > fecha a necessaire','''Necessaire completa nacionais e baratinhos'' animado nos 3s iniciais',true,31,174.6,'observado; hipotese para os comentários (sem CTA no áudio nem na legenda)',1,'Anunciar um desafio com uma regra só no primeiro segundo, com o produto na mão. Passar os produtos em sequência, cerca de 10 s cada, com uma frase de benefício por produto. Fechar mostrando o conjunto. Gera muitos comentários (25,7x a mediana).','Não copiar a regra ''acabamento de luxo'', a necessaire, a lista de produtos nem as frases. Sem comparar com marca famosa (''dupe de'').','2026-11-23'),
('transformacao-trend','Transformação com áudio em alta','https://www.instagram.com/reel/Df8Es00tx2_/','camilapudim',9.04,8.92,'make artística (trend)','dublagem de áudio viral + troca de visual no 1º segundo','vaqueira > gata > transição com chapéu > cabelo cacheado > nariz de vaca > make de vaca completa','nenhum',false,6,19.9,'observado; n_cortes contado visualmente',4,'Virada de visual logo no 1º segundo, sincronizada a um áudio viral, sem fala, poucos cortes e menos de 20 s.','Não usar a mesma fantasia, tema (vaca) nem a coreografia. Áudio só se estiver liberado no Instagram para a conta.','2026-11-23'),
('explicacao-tecnica-de-polemica','Explicação de uma reclamação comum','https://www.instagram.com/reel/DfgExcZsTtI/','karenbachini',6.38,6.07,'blush Purple Punch (Fran by FR)','nomear a polêmica (''vamos falar do polêmico'') com resultado já no rosto','resultado (0-8s) > rosto limpo e explicação da fórmula (8-117s) > aplicação correta (117-164s) > ''vídeo completo no canal''','correção ''purple punch*'' e ''vídeo completo no canal''',true,3,164.3,'observado; hipotese (autoridade técnica)',3,'Nomear a reclamação logo de cara com o resultado bonito já no rosto, explicar em linguagem simples por que acontece e mostrar o jeito certo de usar. Autoridade prática: ''o problema não é o produto, é o jeito''.','Não citar a polêmica nem o produto do original. Não falar em termos de química/medicina; só experiência prática dela. Não diminuir marca.','2026-11-23'),
('primeiras-impressoes-lancamento','Primeiras impressões com pergunta direta','https://www.instagram.com/reel/DfdTlD_oeTh/','amandaoligon',3.38,2.19,'blush Dragon Bloom (Fran by FR)','pergunta direta (''vamos testar o blush da Fran?'') + título na tela','produto > embalagem em close > crítica que circula > aplicação em camadas > reação > pergunta final','título ''Blush da Fran'' + legendas automáticas da fala',true,8,83.8,'observado',3,'Pergunta direta no 1º segundo (''vamos testar…?'') com título na tela; produto e embalagem em close; trazer o que dizem por aí; aplicar em camadas; reação genuína no espelho; pergunta final para comentários.','Não copiar as falas (''Barbie girl'', ''número 1 de blush'') nem o enquadramento da criadora. A crítica que circula tem de ser real, não inventada.','2026-11-23')
